SELECT 'gongkao', '截位直除', 'kp-xingce-data-calc-trunc-div', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "截位直除法"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "处理复杂除法的估算技巧：分母四舍五入留前几位，分子不动直接除。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "贯穿资料分析 80% 的计算。只要列出的算式是 A÷B 的形式，且选项首位或第二位存在差异，都应首选截位直除。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不改变除法本质，只缩短除数位数。"}]}, {"type": "katexBlock", "attrs": {"content": "\\frac{被除数}{除数} \\approx \\frac{分子}{分母截取前N位}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出除法算式 A / B] --> B[观察四个选项的差距]\nB -- 首位不同/前两位差>10% --> C[分母四舍五入保留前 2 位有效数字]\nB -- 首位相同/前两位极接近 --> D[分母四舍五入保留前 3 位有效数字]\nC --> E[分子不动或直接去除非零部分]\nD --> E\nE --> F[直除得出商的前1-2位, 对比选项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某省棉花产量 67843 吨，面积 3241 公顷。求单位面积产量约是多少吨/公顷？选项：A. 18.5  B. 20.9  C. 23.4  D. 26.2"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列式：67843 ÷ 3241。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看选项：首位有 1、2，第二位有 8, 0, 3, 6，差距很大。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定截位：分母保留前两位。3241 前两位是 32，第三位是 4，四舍五入舍去。分母估为 32。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "直除：算 678 ÷ 32。商首位为 2 (余3)，第二位为 1。商序列约 21 开头。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "选出答案：最接近 21 的选项是 B (20.9)。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分子切忌随便截位：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多初学者喜欢把分子和分母同时四舍五入。千万不要！双重截位会成倍放大误差。正确的做法是：只截分母，分子原封不动地作被除数！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "每天抽 5 分钟，随机写 10 组五位数除以四位数的算式，强制只用心算得出商的前两位。练就一秒看破分母截位的功夫。"}]}]}$$ AS jsonb), NULL, '截位直除的核心考点与实战推导。', category_node.id, CAST('["资料分析", "截位直除"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_calc_trunc_div", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
